import React, { useEffect, useState } from "react";
import { motion, useAnimation } from "framer-motion";

const WorkerSplash = ({ onComplete }) => {
  const [impact, setImpact] = useState(false);
  const [isExiting, setIsExiting] = useState(false);

  useEffect(() => {
    // Sequence of "Stamps"
    const timer1 = setTimeout(() => setImpact(true), 600);
    const timer2 = setTimeout(() => setIsExiting(true), 3000);
    const timer3 = setTimeout(onComplete, 3800);

    return () => {
      clearTimeout(timer1);
      clearTimeout(timer2);
      clearTimeout(timer3);
    };
  }, [onComplete]);

  return (
    <div className={`h-screen w-full bg-[#FDFAD8] flex flex-col items-center justify-center relative overflow-hidden ${impact ? "animate-impact" : ""}`}>

      {/* 1. THE EXIT SHUTTER */}
      {isExiting && (
        <div className="absolute inset-0 bg-[#47510B] z-50 animate-garage" />
      )}

      {/* 2. BACKGROUND: Industrial "Caution" Stripes */}
      <div className="absolute top-0 w-full h-8 bg-repeating-linear-gradient opacity-20" 
           style={{ backgroundImage: 'repeating-linear-gradient(45deg, #47510B, #47510B 20px, #CAD23C 20px, #CAD23C 40px)' }} />
      <div className="absolute bottom-0 w-full h-8 bg-repeating-linear-gradient opacity-20" 
           style={{ backgroundImage: 'repeating-linear-gradient(45deg, #47510B, #47510B 20px, #CAD23C 20px, #CAD23C 40px)' }} />

      {/* 3. THE MAIN LOGO UNIT */}
      <div className="flex flex-col items-center">
        <div className="flex items-end gap-1">
          {/* T1 */}
          <motion.h1 
            initial={{ scale: 4, opacity: 0 }}
            animate={{ scale: 1, opacity: 1 }}
            transition={{ duration: 0.2, delay: 0.4 }}
            className="text-[12rem] md:text-[18rem] font-[1000] text-[#47510B] leading-[0.8] tracking-tighter"
          >
            T
          </motion.h1>

          {/* THE 2 (Floating High-Vis Block) */}
          <motion.div 
            initial={{ y: -600 }}
            animate={{ y: 0 }}
            transition={{ type: "spring", stiffness: 300, damping: 15, delay: 0.7 }}
            className="bg-[#FF5B03] px-6 py-2 border-[10px] border-[#47510B] shadow-[12px_12px_0px_#2A3106] -rotate-6 mb-12"
          >
            <span className="text-white text-9xl font-black italic">2</span>
          </motion.div>

          {/* T2 */}
          <motion.h1 
            initial={{ scale: 4, opacity: 0 }}
            animate={{ scale: 1, opacity: 1 }}
            transition={{ duration: 0.2, delay: 0.5 }}
            className="text-[12rem] md:text-[18rem] font-[1000] text-[#47510B] leading-[0.8] tracking-tighter"
          >
            T
          </motion.h1>
        </div>

        {/* 4. THE "WORKER" BOX */}
        <motion.div 
          initial={{ opacity: 0, x: -100 }}
          animate={{ opacity: 1, x: 0 }}
          transition={{ delay: 1.2 }}
          className="bg-[#47510B] text-[#FFF24D] px-12 py-3 mt-4 flex items-center gap-4 border-b-8 border-[#2A3106]"
        >
          <div className="w-4 h-4 rounded-full bg-[#FF5B03] animate-pulse" />
          <span className="font-black text-3xl italic tracking-widest uppercase">Worker</span>
          <div className="w-4 h-4 rounded-full bg-[#FF5B03] animate-pulse" />
        </motion.div>
      </div>

      {/* 5. DYNAMIC FOOTER READOUT */}
      <div className="absolute bottom-16 font-mono text-[10px] text-[#47510B] font-bold tracking-[0.5em] flex flex-col items-center">
          <p className="opacity-40 uppercase">Hydraulic_Pressure: 2800_PSI</p>
          <p className="text-[#AB1717] mt-1">STATUS: READY_FOR_DISPATCH</p>
      </div>
    </div>
  );
};

export default WorkerSplash;
